#include "protocol.h"
static uint16_t crc16(const uint8_t *p,uint16_t n){uint16_t c=0xffff;for(uint16_t i=0;i<n;i++){c^=(uint16_t)p[i]<<8;for(uint8_t b=0;b<8;b++)c=(c&0x8000)?(uint16_t)((c<<1)^0x1021):(uint16_t)(c<<1);}return c;}
int pp_encode(const pp_msg_t*m,uint8_t*o,uint16_t cap){if(!m||!o||m->version!=PP_VERSION||m->len>PP_MAX_PAYLOAD||cap<(uint16_t)(11+m->len))return -1;o[0]=m->version;o[1]=m->node;o[2]=m->type;o[3]=m->seq;for(int i=0;i<4;i++)o[4+i]=(uint8_t)(m->epoch_s>>(8*i));o[8]=m->len;for(uint8_t i=0;i<m->len;i++)o[9+i]=m->payload[i];uint16_t c=crc16(o,9+m->len);o[9+m->len]=(uint8_t)c;o[10+m->len]=(uint8_t)(c>>8);return 11+m->len;}
int pp_decode(const uint8_t*i,uint16_t n,pp_msg_t*m){if(!i||!m||n<11||i[0]!=PP_VERSION||i[8]>PP_MAX_PAYLOAD||n!=(uint16_t)(11+i[8]))return -1;uint16_t c=crc16(i,n-2);if(i[n-2]!=(uint8_t)c||i[n-1]!=(uint8_t)(c>>8))return -2;m->version=i[0];m->node=i[1];m->type=i[2];m->seq=i[3];m->epoch_s=(uint32_t)i[4]|((uint32_t)i[5]<<8)|((uint32_t)i[6]<<16)|((uint32_t)i[7]<<24);m->len=i[8];for(uint8_t x=0;x<m->len;x++)m->payload[x]=i[9+x];return 0;}
